#include <fstream>
#include <vector>
#include <string>
#include <climits>
using namespace std;
int main(){
    ifstream in("perimeter.in"); ofstream out("perimeter.out");
    int n; in>>n; vector<string> g(n);for(auto &row:g)in>>row;
    vector<unsigned char> used(n*n,0);
    int bestArea=0,bestPerimeter=INT_MAX;
    const int dr[4]={-1,1,0,0},dc[4]={0,0,-1,1};
    for(int r=0;r<n;r++)for(int c=0;c<n;c++){
        int start=r*n+c;
        if(g[r][c]!='#'||used[start])continue;
        vector<int> stack(1,start);used[start]=1;
        int area=0,perimeter=0;
        while(!stack.empty()){
            int id=stack.back();stack.pop_back();++area;
            int x=id/n,y=id%n;
            for(int d=0;d<4;d++){
                int a=x+dr[d],b=y+dc[d];
                if(a<0||a>=n||b<0||b>=n||g[a][b]=='.')++perimeter;
                else if(!used[a*n+b]){used[a*n+b]=1;stack.push_back(a*n+b);}
            }
        }
        if(area>bestArea||(area==bestArea&&perimeter<bestPerimeter)){
            bestArea=area;bestPerimeter=perimeter;
        }
    }
    out<<bestArea<<' '<<bestPerimeter<<'\n';
}
