#include <fstream>
#include <vector>
#include <utility>
#include <algorithm>
#include <climits>
using namespace std;
int main(){
    ifstream in("mountains.in");ofstream out("mountains.out");
    int n;in>>n;vector<pair<long long,long long>> intervals;
    for(int i=0;i<n;i++){
        long long x,y;in>>x>>y;intervals.push_back({x-y,x+y});
    }
    sort(intervals.begin(),intervals.end(),[](auto a,auto b){
        if(a.first!=b.first)return a.first<b.first;
        return a.second>b.second;
    });
    long long furthest=LLONG_MIN;int visible=0;
    for(auto [left,right]:intervals){
        (void)left;
        if(right>furthest){++visible;furthest=right;}
    }
    out<<visible<<'\n';
}
